export { view } from "../separator";
export type {
  SeparatorOrientation,
  SeparatorStyle,
  ViewConfig,
} from "../separator";

export {
  shadcnHorizontalSeparatorClassName,
  shadcnSeparatorBaseClassName,
  shadcnSeparatorClassNameByOrientation,
  shadcnVerticalSeparatorClassName,
} from "./view";

export {
  horizontalSeparatorClassName as shadcnHorizontalSeparatorClassName,
  separatorBaseClassName as shadcnSeparatorBaseClassName,
  separatorClassNameByOrientation as shadcnSeparatorClassNameByOrientation,
  verticalSeparatorClassName as shadcnVerticalSeparatorClassName,
} from "../separator/view";

import { describe, expect, test } from "vitest";

import * as Separator from "./index";

describe("shadcn Separator registry view", () => {
  test("reuses the Foldkit Separator view contract", () => {
    expect(Separator.view).toBeTypeOf("function");
    expect(
      Separator.shadcnSeparatorClassNameByOrientation("vertical")
    ).toContain("w-px");
    expect(Separator.shadcnSeparatorBaseClassName).toContain("shrink-0");
  });
});
